using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class LabDoorInspect {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/검수/2026-11-07_C01_Doors/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");Directory.CreateDirectory(O);var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(d=>Vector3.Distance(d.position,room.position)<12).ToArray();var f=JObject.Parse(File.ReadAllText(R+"/Docs/도면/Decision/원형공동/facility_layout.json"))["floors"].Single(f=>(string)f["id"]=="B5");var result=new{scene=s.path,dirty=s.isDirty,room=room.position.ToString("F5"),tunnels=f["tunnels"].Where(t=>(string)t["a"]=="C01"||(string)t["b"]=="C01").ToArray(),doors=doors.Select(d=>new{d.name,p=d.position.ToString("F5"),rot=d.eulerAngles.ToString("F5"),children=d.GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,path=AssetDatabase.GetAssetPath(m.sharedMesh),localCenter=d.InverseTransformPoint(m.GetComponent<Renderer>().bounds.center).ToString("F5"),size=m.sharedMesh.bounds.size.ToString("F5"),scale=m.transform.lossyScale.ToString("F5"),materials=m.GetComponent<Renderer>().sharedMaterials.Select(x=>AssetDatabase.GetAssetPath(x)).ToArray()}).ToArray()}).ToArray(),stations=room.Find("C01_Perimeter_Lab").Cast<Transform>().Select(t=>new{t.name,p=t.localPosition.ToString("F6"),r=t.localEulerAngles.ToString("F6"),s=t.localScale.ToString("F6")}).ToArray(),player=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).Select(g=>new{g.name,p=g.transform.position.ToString("F6"),r=g.transform.eulerAngles.ToString("F6")}).ToArray()};File.WriteAllText(O+"before.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
